//! Runtime dogma graph for one request. Modifier *registration* is compiled code (`data::apply_local`,
//! `data::apply_projected`, `data::apply_dbuff`, generated by build.rs); this file only provides the target
//! selectors those generated calls use, plus lazy memoised evaluation.
//!
//! Semantics follow the reference engine eve-dogma-rs (LGPL-3.0-or-later), which this file is derived from.
use crate::data::{self as d, a, e};
use crate::request::{FitRequest, ModuleReq, Slot, Spool, State};
use std::cell::Cell;

/// Source categories exempt from stacking penalties: Ship, Charge, Skill, Implant, Subsystem, Structure.
const EXEMPT_CATEGORIES: [u32; 6] = [6, 8, 16, 20, 32, 65];
pub const ATTR_SKILL_LEVEL: u16 = 280;
const BUFF_PAIRS: [(u16, u16); 4] = [
    (a::warfareBuff1ID, a::warfareBuff1Value),
    (a::warfareBuff2ID, a::warfareBuff2Value),
    (a::warfareBuff3ID, a::warfareBuff3Value),
    (a::warfareBuff4ID, a::warfareBuff4Value),
];
/// Pilot skill effects that still apply to structures.
const STRUCTURE_SKILL_EFFECTS: [u32; 5] = [
    e::targetingMaxTargetBonusModAddMaxLockedTargetsLocationChar,
    e::skillStructureMissileDamageBonus,
    e::skillStructureElectronicSystemsCapNeedBonus,
    e::skillStructureEngineeringSystemsCapNeedBonus,
    e::skillStructureDoomsdayDurationBonus,
];

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Kind {
    Ship,
    Char,
    Skill,
    Module,
    Charge,
    Drone,
    Fighter,
    Implant,
    Booster,
    Mode,
    Beacon,
    Projected,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Loc {
    Ship,
    Char,
    Space,
    Nowhere,
}

#[derive(Debug, Clone, Copy)]
pub enum Src {
    Attr { item: u32, attr: u16 },
    Const(f64),
    /// AB/MWD: 1 + speedFactor/100 * speedBoostFactor / ship mass (PostMul)
    Prop { module: u32 },
    /// projected: source value (evaluated on the projecting item) scaled by range factor and, lazily, by the
    /// target ship's resistance attribute
    Projected { v: f64, factor: f64, resist: u16, mul: bool },
}

const NONE: u32 = u32::MAX;

#[derive(Debug, Clone, Copy)]
pub struct AMod {
    pub op: i8,
    pub pen: bool,
    pub src: Src,
}

pub struct Slot_ {
    pub base: f64,
    /// head of this slot's modifier chain in `Fit::mods` (NONE = no modifiers); order is irrelevant to eval
    head: u32,
    n: u32,
    val: Cell<f64>,
    /// 0 = not computed, 1 = computing (cycle guard), 2 = cached
    st: Cell<u8>,
}

pub struct Item {
    pub ty: usize,
    pub type_id: u32,
    pub group: u32,
    pub category: u32,
    pub kind: Kind,
    pub state: State,
    pub loc: Loc,
    pub owned: bool,
    pub parent: Option<usize>,
    pub charge: Option<usize>,
    pub slot: Option<Slot>,
    pub req_index: Option<usize>,
    pub quantity: u32,
    pub active_count: u32,
    /// attributes that differ from the static type table (modified / overridden / mutated), sorted by attr id
    pub dyn_attrs: Vec<(u16, u32)>,
    pub req_skills: &'static [u32],
    /// packed effect refs (dense index << 1 | is_default); static type list + extra (mutation base)
    pub effs: &'static [u16],
    pub extra_effs: Vec<u16>,
    pub fighter_abilities: Vec<u32>,
    pub booster_side_effects: Vec<u32>,
    pub spool: Option<Spool>,
    pub distance: Option<f64>,
}

impl Item {
    pub fn effects(&self) -> impl Iterator<Item = (usize, bool)> + '_ {
        self.effs.iter().chain(self.extra_effs.iter()).map(|x| ((x >> 1) as usize, x & 1 != 0))
    }
    pub fn has_effect(&self, id: u32) -> bool {
        self.effects().any(|(ei, _)| d::EFF_IDS[ei] == id)
    }
}

pub struct Fit {
    pub items: Vec<Item>,
    pub slots: Vec<Slot_>,
    /// modifier arena: (modifier, next index in the same slot's chain)
    mods: Vec<(AMod, u32)>,
    pub ship: usize,
    pub char: usize,
    pub warnings: Vec<String>,
    pub is_structure: bool,
    ship_items: Vec<u32>,
    char_items: Vec<u32>,
    /// (group, item) sorted
    by_group: Vec<(u32, u32)>,
    /// (required skill, item) sorted
    by_skill: Vec<(u32, u32)>,
    /// every skill level of the character (folded or instantiated), sorted by skill id
    pub skill_levels: Vec<(u32, u8)>,
    /// while set, only Item/Other-domain modifiers are applied (charges of projected modules)
    restrict: bool,
    /// published skills handled by compiled, level-folded code: (index into PUBLISHED_SKILLS, level)
    folded: Vec<(u16, u8)>,
    /// projected fits: (fit, amount, distance)
    ext: Vec<(Fit, u32, Option<f64>)>,
    /// incoming remote repairs (Pyfa RR lists): kind 0 shield / 1 armor / 2 hull, amount per cycle, cycle s
    pub rr: Vec<(u8, f64, f64)>,
    /// incoming cap drains/fills (neuts, nos, transfers) for the cap simulation
    pub ext_drains: Vec<ExtDrain>,
    /// incoming ECM jammers
    pub ext_ecm: Vec<ExtEcm>,
    /// active AB/MWD modules (Pyfa runs them in module order: each reads ship mass after its own and earlier
    /// prop modules' massAddition, not later ones)
    pub props: Vec<u32>,
}

#[derive(Debug, Clone, Copy)]
pub struct ExtDrain {
    pub cycle_ms: f64,
    /// cap removed per cycle before resistance / signature scaling (negative = cap added)
    pub amount: f64,
    pub resist: u16,
    pub sig_res: f64,
    /// Pyfa handler runs 'late' (nosferatu): sees the target's full signature radius incl. MWD bloom
    pub late: bool,
    pub assistance: bool,
}

/// One effect projected onto this fit, fully evaluated on the projecting side.
const SKILL_GUNNERY: u32 = 3300;
const SKILL_MISSILE_LAUNCHER_OPERATION: u32 = 3319;
const SKILL_DRONES: u32 = 3436;
const SMART_BOMB_GROUP: u32 = 72;
const PROPULSION_MODULE_GROUP: u32 = 46;

enum ProjAction {
    /// `off`: offensive fighter ability (dropped on targets with disallowOffensiveModifiers)
    Mod { attr: u16, op: i8, v: f64, factor: f64, resist: u16, pen: bool, off: bool },
    Rr { kind: u8, amount: f64, dur_s: f64 },
    /// Pyfa filteredItemBoost / filteredChargeBoost on the target's modules (or their charges) requiring `skill`:
    /// postPercent, stacking-penalised, offensive (tracking / guidance disruptors).
    /// `assist`: assistance effect (blocked by the target's disallowAssistance) instead of an offensive one.
    ModItems { skill: u32, charge: bool, attr: u16, v: f64, factor: f64, resist: u16, assist: bool },
    Drain(ExtDrain),
    /// ECM jam strengths (magnetometric, ladar, radar, gravimetric) already scaled by range/squadron, + resist attr
    Ecm { st: [f64; 4], resist: u16 },
    Warn(String),
}

/// Incoming ECM (Pyfa addProjectedEcm): strengths per sensor type, target resistance attribute.
#[derive(Debug, Clone, Copy)]
pub struct ExtEcm {
    pub st: [f64; 4],
    pub resist: u16,
}

#[derive(Debug)]
pub struct EngineError {
    pub code: &'static str,
    pub message: String,
    pub path: String,
}

fn state_name(s: State) -> &'static str {
    match s {
        State::Offline => "offline",
        State::Online => "online",
        State::Active => "active",
        State::Overheated => "overheated",
    }
}

fn state_ok(category: u8, state: State) -> bool {
    match category {
        0 | 4 => state >= State::Online,
        1 => state >= State::Active,
        5 => state >= State::Overheated,
        7 => true,
        _ => false,
    }
}

fn range_of(v: &[(u32, u32)], key: u32) -> std::ops::Range<usize> {
    let lo = v.partition_point(|x| x.0 < key);
    let hi = lo + v[lo..].partition_point(|x| x.0 <= key);
    lo..hi
}

impl Fit {
    fn new_item(&mut self, type_id: u32, kind: Kind, loc: Loc, path: &str) -> Result<usize, EngineError> {
        let ty = d::type_index(type_id).ok_or_else(|| EngineError {
            code: "UNKNOWN_TYPE",
            message: format!("unknown type_id {type_id}"),
            path: path.to_string(),
        })?;
        let t = d::ty(ty);
        self.items.push(Item {
            ty,
            type_id,
            group: t.group,
            category: t.category,
            kind,
            state: State::Online,
            loc,
            owned: matches!(kind, Kind::Module | Kind::Charge | Kind::Drone | Kind::Fighter | Kind::Ship),
            parent: None,
            charge: None,
            slot: None,
            req_index: None,
            quantity: 1,
            active_count: 0,
            dyn_attrs: Vec::new(),
            req_skills: d::type_req_skills(ty),
            effs: d::type_effects(ty),
            extra_effs: Vec::new(),
            fighter_abilities: Vec::new(),
            booster_side_effects: Vec::new(),
            spool: None,
            distance: None,
        });
        Ok(self.items.len() - 1)
    }

    // ------------------------------------------------------------ attribute storage
    #[inline]
    fn slot_of(&self, i: usize, attr: u16) -> Option<u32> {
        let v = &self.items[i].dyn_attrs;
        if v.is_empty() {
            return None;
        }
        v.binary_search_by_key(&attr, |x| x.0).ok().map(|k| v[k].1)
    }

    /// Set (or replace) the base value of an attribute on an item.
    pub fn set_base(&mut self, i: usize, attr: u16, base: f64) {
        match self.items[i].dyn_attrs.binary_search_by_key(&attr, |x| x.0) {
            Ok(k) => {
                let s = self.items[i].dyn_attrs[k].1 as usize;
                self.slots[s] = Slot_ { base, head: NONE, n: 0, val: Cell::new(0.0), st: Cell::new(0) };
            }
            Err(k) => {
                self.slots.push(Slot_ { base, head: NONE, n: 0, val: Cell::new(0.0), st: Cell::new(0) });
                let s = (self.slots.len() - 1) as u32;
                self.items[i].dyn_attrs.insert(k, (attr, s));
            }
        }
    }

    fn ensure(&mut self, i: usize, attr: u16) -> usize {
        match self.items[i].dyn_attrs.binary_search_by_key(&attr, |x| x.0) {
            Ok(k) => self.items[i].dyn_attrs[k].1 as usize,
            Err(k) => {
                let base = d::type_attr(self.items[i].ty, attr).unwrap_or_else(|| d::attr_default(attr));
                self.slots.push(Slot_ { base, head: NONE, n: 0, val: Cell::new(0.0), st: Cell::new(0) });
                let s = self.slots.len() - 1;
                let da = &mut self.items[i].dyn_attrs;
                if da.capacity() == 0 {
                    da.reserve(if i < 2 { 160 } else { 24 });
                }
                da.insert(k, (attr, s as u32));
                s
            }
        }
    }

    #[inline]
    fn push(&mut self, t: usize, attr: u16, op: i8, pen: bool, src: Src) {
        let s = self.ensure(t, attr);
        let k = self.mods.len() as u32;
        self.mods.push((AMod { op, pen, src }, self.slots[s].head));
        self.slots[s].head = k;
        self.slots[s].n += 1;
    }

    pub fn has(&self, i: usize, attr: u16) -> bool {
        self.slot_of(i, attr).is_some() || d::type_attr(self.items[i].ty, attr).is_some()
    }

    pub fn base(&self, i: usize, attr: u16) -> f64 {
        match self.slot_of(i, attr) {
            Some(s) => self.slots[s as usize].base,
            None => d::type_attr(self.items[i].ty, attr).unwrap_or_else(|| d::attr_default(attr)),
        }
    }

    pub fn base_opt(&self, i: usize, attr: u16) -> Option<f64> {
        match self.slot_of(i, attr) {
            Some(s) => Some(self.slots[s as usize].base),
            None => d::type_attr(self.items[i].ty, attr),
        }
    }

    /// All attribute ids present on an item (sorted).
    pub fn attr_ids(&self, i: usize) -> Vec<u16> {
        let mut v: Vec<u16> = d::type_attr_ids(self.items[i].ty).to_vec();
        v.extend(self.items[i].dyn_attrs.iter().map(|x| x.0));
        v.sort_unstable();
        v.dedup();
        v
    }

    // ------------------------------------------------------------ target selectors used by generated code
    #[inline]
    pub fn m_item(&mut self, t: usize, modified: u16, op: i8, src: usize, sa: u16, pen: bool) {
        if self.restrict && (t == self.ship || t == self.char) {
            return;
        }
        self.push(t, modified, op, pen, Src::Attr { item: src as u32, attr: sa });
    }
    pub fn m_other(&mut self, modified: u16, op: i8, i: usize, sa: u16, pen: bool) {
        let it = &self.items[i];
        if let Some(t) = it.charge.or(it.parent) {
            self.m_item(t, modified, op, i, sa, pen);
        }
    }
    pub fn m_ship_loc(&mut self, modified: u16, op: i8, i: usize, sa: u16, pen: bool) {
        if self.restrict {
            return;
        }
        for k in 0..self.ship_items.len() {
            let t = self.ship_items[k] as usize;
            self.m_item(t, modified, op, i, sa, pen);
        }
    }
    pub fn m_ship_group(&mut self, g: u32, modified: u16, op: i8, i: usize, sa: u16, pen: bool) {
        if self.restrict {
            return;
        }
        for k in range_of(&self.by_group, g) {
            let t = self.by_group[k].1 as usize;
            if self.items[t].loc == Loc::Ship {
                self.m_item(t, modified, op, i, sa, pen);
            }
        }
    }
    pub fn m_ship_skill(&mut self, s: u32, modified: u16, op: i8, i: usize, sa: u16, pen: bool) {
        if self.restrict {
            return;
        }
        for k in range_of(&self.by_skill, s) {
            let t = self.by_skill[k].1 as usize;
            if self.items[t].loc == Loc::Ship {
                self.m_item(t, modified, op, i, sa, pen);
            }
        }
    }
    pub fn m_owner_skill(&mut self, s: u32, modified: u16, op: i8, i: usize, sa: u16, pen: bool) {
        if self.restrict {
            return;
        }
        for k in range_of(&self.by_skill, s) {
            let t = self.by_skill[k].1 as usize;
            if self.items[t].owned {
                self.m_item(t, modified, op, i, sa, pen);
            }
        }
    }
    pub fn m_char_loc(&mut self, modified: u16, op: i8, i: usize, sa: u16, pen: bool) {
        if self.restrict {
            return;
        }
        for k in 0..self.char_items.len() {
            let t = self.char_items[k] as usize;
            self.m_item(t, modified, op, i, sa, pen);
        }
    }
    pub fn m_char_group(&mut self, g: u32, modified: u16, op: i8, i: usize, sa: u16, pen: bool) {
        if self.restrict {
            return;
        }
        for k in range_of(&self.by_group, g) {
            let t = self.by_group[k].1 as usize;
            if self.items[t].loc == Loc::Char {
                self.m_item(t, modified, op, i, sa, pen);
            }
        }
    }
    pub fn m_char_skill(&mut self, s: u32, modified: u16, op: i8, i: usize, sa: u16, pen: bool) {
        if self.restrict {
            return;
        }
        for k in range_of(&self.by_skill, s) {
            let t = self.by_skill[k].1 as usize;
            let it = &self.items[t];
            if (it.owned || it.loc == Loc::Char) && it.kind != Kind::Skill {
                self.m_item(t, modified, op, i, sa, pen);
            }
        }
    }
    // folded skill modifiers: constant source, skills are exempt from stacking penalties
    #[inline]
    pub fn c_item(&mut self, t: usize, modified: u16, op: i8, v: f64) {
        self.push(t, modified, op, false, Src::Const(v));
    }
    pub fn c_ship_loc(&mut self, modified: u16, op: i8, v: f64) {
        for k in 0..self.ship_items.len() {
            let t = self.ship_items[k] as usize;
            self.c_item(t, modified, op, v);
        }
    }
    pub fn c_ship_group(&mut self, g: u32, modified: u16, op: i8, v: f64) {
        for k in range_of(&self.by_group, g) {
            let t = self.by_group[k].1 as usize;
            if self.items[t].loc == Loc::Ship {
                self.c_item(t, modified, op, v);
            }
        }
    }
    pub fn c_ship_skill(&mut self, s: u32, modified: u16, op: i8, v: f64) {
        for k in range_of(&self.by_skill, s) {
            let t = self.by_skill[k].1 as usize;
            if self.items[t].loc == Loc::Ship {
                self.c_item(t, modified, op, v);
            }
        }
    }
    pub fn c_owner_skill(&mut self, s: u32, modified: u16, op: i8, v: f64) {
        for k in range_of(&self.by_skill, s) {
            let t = self.by_skill[k].1 as usize;
            if self.items[t].owned {
                self.c_item(t, modified, op, v);
            }
        }
    }
    pub fn c_char_group(&mut self, g: u32, modified: u16, op: i8, v: f64) {
        for k in range_of(&self.by_group, g) {
            let t = self.by_group[k].1 as usize;
            if self.items[t].loc == Loc::Char {
                self.c_item(t, modified, op, v);
            }
        }
    }
    pub fn c_char_skill(&mut self, s: u32, modified: u16, op: i8, v: f64) {
        for k in range_of(&self.by_skill, s) {
            let t = self.by_skill[k].1 as usize;
            let it = &self.items[t];
            if (it.owned || it.loc == Loc::Char) && it.kind != Kind::Skill {
                self.c_item(t, modified, op, v);
            }
        }
    }
    // warfare buffs (never exempt from stacking)
    pub fn b_item(&mut self, attr: u16, op: i8, src: Src, _s: usize) {
        let ship = self.ship;
        self.push(ship, attr, op, !d::attr_stackable(attr), src);
    }
    pub fn b_loc(&mut self, attr: u16, op: i8, src: Src, _s: usize) {
        for k in 0..self.ship_items.len() {
            let t = self.ship_items[k] as usize;
            self.push(t, attr, op, !d::attr_stackable(attr), src);
        }
    }
    pub fn b_group(&mut self, attr: u16, g: u32, op: i8, src: Src, _s: usize) {
        for k in range_of(&self.by_group, g) {
            let t = self.by_group[k].1 as usize;
            if self.items[t].loc == Loc::Ship {
                self.push(t, attr, op, !d::attr_stackable(attr), src);
            }
        }
    }
    pub fn b_skill(&mut self, attr: u16, s: u32, op: i8, src: Src, _s: usize) {
        for k in range_of(&self.by_skill, s) {
            let t = self.by_skill[k].1 as usize;
            if self.items[t].loc == Loc::Ship {
                self.push(t, attr, op, !d::attr_stackable(attr), src);
            }
        }
    }
    // effects without modifierInfo (compiled to these calls by build.rs)
    pub fn sp_prop(&mut self, i: usize, mwd: bool, p: bool) {
        let ship = self.ship;
        self.props.push(i as u32);
        self.push(ship, a::mass, 2, p && !d::attr_stackable(a::mass), Src::Attr { item: i as u32, attr: a::massAddition });
        self.push(ship, a::maxVelocity, 4, p && !d::attr_stackable(a::maxVelocity), Src::Prop { module: i as u32 });
        if mwd {
            self.push(
                ship,
                a::signatureRadius,
                6,
                p && !d::attr_stackable(a::signatureRadius),
                Src::Attr { item: i as u32, attr: a::signatureRadiusBonus },
            );
        }
    }
    pub fn sp_mjd(&mut self, i: usize) {
        let ship = self.ship;
        // MJD sig bloom is not stacking-penalised (unlike the MWD's)
        self.push(ship, a::signatureRadius, 6, false, Src::Attr { item: i as u32, attr: a::signatureRadiusBonusPercent });
    }
    /// lances / disruptive lances: ship speed boost (penalised) + warp scramble status
    pub fn sp_lance(&mut self, i: usize, p: bool) {
        let ship = self.ship;
        self.push(ship, a::maxVelocity, 6, p && !d::attr_stackable(a::maxVelocity), Src::Attr { item: i as u32, attr: a::speedFactor });
        self.push(ship, a::warpScrambleStatus, 2, false, Src::Attr { item: i as u32, attr: a::siegeModeWarpStatus });
    }
    /// warp disruption field generator (local part): no assistance; uncharged = HIC bubble bonuses (unpenalised)
    pub fn sp_wdfg(&mut self, i: usize) {
        let ship = self.ship;
        self.push(ship, a::disallowAssistance, 7, false, Src::Const(1.0));
        if self.items[i].charge.is_some() {
            return;
        }
        let s = |attr| Src::Attr { item: i as u32, attr };
        self.push(ship, a::mass, 6, false, s(a::massBonusPercentage));
        self.push(ship, a::signatureRadius, 6, false, s(a::signatureRadiusBonus));
        for k in range_of(&self.by_group, PROPULSION_MODULE_GROUP) {
            let t = self.by_group[k].1 as usize;
            if self.items[t].kind == Kind::Module {
                self.push(t, a::speedBoostFactor, 6, false, s(a::speedBoostFactorBonus));
                self.push(t, a::speedFactor, 6, false, s(a::speedFactorBonus));
            }
        }
    }
    pub fn sp_entosis(&mut self, i: usize, p: bool) {
        let ship = self.ship;
        self.push(ship, a::disallowAssistance, 7, false, Src::Attr { item: i as u32, attr: a::disallowAssistance });
        for (t, s) in [
            (a::scanGravimetricStrength, a::scanGravimetricStrengthPercent),
            (a::scanMagnetometricStrength, a::scanMagnetometricStrengthPercent),
            (a::scanRadarStrength, a::scanRadarStrengthPercent),
            (a::scanLadarStrength, a::scanLadarStrengthPercent),
        ] {
            self.push(ship, t, 6, p && !d::attr_stackable(t), Src::Attr { item: i as u32, attr: s });
        }
    }
    /// incursion system effects (Pyfa OffensiveDefensiveReduction), all unpenalised PostPercent
    pub fn sp_incursion(&mut self, i: usize) {
        let ship = self.ship;
        let src = |attr| Src::Attr { item: i as u32, attr };
        let red = src(a::systemEffectDamageReduction);
        let dmg = [a::emDamage, a::thermalDamage, a::kineticDamage, a::explosiveDamage];
        for t in 0..self.items.len() {
            let it = &self.items[t];
            let charge_ml = it.kind == Kind::Charge && it.loc == Loc::Ship && it.req_skills.contains(&SKILL_MISSILE_LAUNCHER_OPERATION);
            let smartbomb = it.kind == Kind::Module && it.group == SMART_BOMB_GROUP;
            if charge_ml || smartbomb {
                for &x in &dmg {
                    self.push(t, x, 6, false, red);
                }
            }
            let it = &self.items[t];
            if it.kind == Kind::Drone || (it.kind == Kind::Module && it.req_skills.contains(&SKILL_GUNNERY)) {
                self.push(t, a::damageMultiplier, 6, false, red);
            }
        }
        for (r, b) in [
            (a::armorEmDamageResonance, a::armorEmDamageResistanceBonus),
            (a::armorThermalDamageResonance, a::armorThermalDamageResistanceBonus),
            (a::armorKineticDamageResonance, a::armorKineticDamageResistanceBonus),
            (a::armorExplosiveDamageResonance, a::armorExplosiveDamageResistanceBonus),
            (a::shieldEmDamageResonance, a::shieldEmDamageResistanceBonus),
            (a::shieldThermalDamageResonance, a::shieldThermalDamageResistanceBonus),
            (a::shieldKineticDamageResonance, a::shieldKineticDamageResistanceBonus),
            (a::shieldExplosiveDamageResonance, a::shieldExplosiveDamageResistanceBonus),
        ] {
            self.push(ship, r, 6, false, src(b));
        }
    }
    /// apply one warfare buff like Pyfa's Fit.__runCommandBoosts: the dataset's dbuff modifiers, except for the
    /// abyssal weather buffs (unpenalised) and the drone scope of buffs 79, 90, 93-99.
    fn apply_buff(&mut self, id: u32, src: Src, s: usize) {
        let ship = self.ship;
        let hull_res = |k: u32| -> &'static [u16] {
            match k {
                90 => &[a::shieldEmDamageResonance, a::armorEmDamageResonance, a::emDamageResonance],
                93 => &[a::shieldExplosiveDamageResonance, a::armorExplosiveDamageResonance, a::explosiveDamageResonance],
                94 => &[a::shieldCapacity],
                95 => &[a::shieldThermalDamageResonance, a::armorThermalDamageResonance, a::thermalDamageResonance],
                96 => &[a::armorHP],
                98 => &[a::maxVelocity],
                99 => &[a::shieldKineticDamageResonance, a::armorKineticDamageResonance, a::kineticDamageResonance],
                _ => &[],
            }
        };
        let unpen = hull_res(id);
        if !unpen.is_empty() {
            let drones: Vec<usize> = (0..self.items.len()).filter(|&t| self.items[t].kind == Kind::Drone && self.items[t].req_skills.contains(&SKILL_DRONES)).collect();
            for &attr in unpen {
                self.push(ship, attr, 6, false, src);
                for &t in &drones {
                    self.push(t, attr, 6, false, src);
                }
            }
            return;
        }
        d::apply_dbuff(self, id, src, s);
        let drone_attrs: &[u16] = match id {
            79 => &[a::signatureRadius],
            97 => &[a::maxRange, a::falloff],
            _ => &[],
        };
        for t in 0..self.items.len() {
            if self.items[t].kind == Kind::Drone && self.items[t].req_skills.contains(&SKILL_DRONES) {
                for &attr in drone_attrs {
                    self.push(t, attr, 6, !d::attr_stackable(attr), src);
                }
            }
        }
    }
    /// (buff id, value attr) of abyssal weather / AoE cloud beacons in the environment
    fn beacon_buffs(&self) -> Vec<(u32, usize, u16)> {
        let mut v = Vec::new();
        for i in 0..self.items.len() {
            if self.items[i].kind != Kind::Beacon {
                continue;
            }
            let wx = self.items[i].effects().any(|(ei, _)| {
                let n = d::eff_name(ei);
                n.starts_with("weather_") || n.starts_with("aoe_beacon_")
            });
            if !wx {
                continue;
            }
            for (ida, vala) in BUFF_PAIRS {
                let id = if self.has(i, ida) { self.get(i, ida) as u32 } else { 0 };
                if id != 0 {
                    v.push((id, i, vala));
                }
            }
        }
        v
    }
    /// ORE freighter agility bonus: Pyfa boosts agility with stackingPenalties=True (its handlers for the two Bowhead
    /// effects are swapped; the net effect equals the SDE except for the penalty)
    pub fn sp_freighter_agility(&mut self, i: usize) {
        let ship = self.ship;
        self.push(ship, a::agility, 6, true, Src::Attr { item: i as u32, attr: a::freighterBonusO2 });
    }
    /// cyno: unpenalised speed boost only (Pyfa cynosuralGeneration)
    pub fn sp_cyno(&mut self, i: usize) {
        let ship = self.ship;
        self.push(ship, a::maxVelocity, 6, false, Src::Attr { item: i as u32, attr: a::speedFactor });
    }
    pub fn sp_mjfg(&mut self, i: usize, p: bool) {
        let ship = self.ship;
        self.push(ship, a::signatureRadius, 6, p && !d::attr_stackable(a::signatureRadius), Src::Attr { item: i as u32, attr: a::signatureRadiusBonusPercent });
    }
    /// emergency hull energizer: hull resonances x hull*DamageResonance ("postMul" penalty group)
    pub fn sp_ehe(&mut self, i: usize, p: bool) {
        let ship = self.ship;
        for (t, s) in [
            (a::emDamageResonance, a::hullEmDamageResonance),
            (a::thermalDamageResonance, a::hullThermalDamageResonance),
            (a::kineticDamageResonance, a::hullKineticDamageResonance),
            (a::explosiveDamageResonance, a::hullExplosiveDamageResonance),
        ] {
            self.push(ship, t, 4, p && !d::attr_stackable(t), Src::Attr { item: i as u32, attr: s });
        }
    }
    pub fn sp_slot(&mut self, i: usize, p: bool) {
        let ship = self.ship;
        for (t, s) in [(a::hiSlots, a::hiSlotModifier), (a::medSlots, a::medSlotModifier), (a::lowSlots, a::lowSlotModifier)] {
            self.push(ship, t, 2, p && !d::attr_stackable(t), Src::Attr { item: i as u32, attr: s });
        }
    }
    pub fn sp_hardpoint(&mut self, i: usize, p: bool) {
        let ship = self.ship;
        for (t, s) in [(a::turretSlotsLeft, a::turretHardPointModifier), (a::launcherSlotsLeft, a::launcherHardPointModifier)] {
            self.push(ship, t, 2, p && !d::attr_stackable(t), Src::Attr { item: i as u32, attr: s });
        }
    }

    // ------------------------------------------------------------ build
    fn apply_mutation(&mut self, idx: usize, m: &crate::request::Mutation) {
        if let Some(bix) = d::type_index(m.base_type_id) {
            let own_ty = self.items[idx].ty;
            for &aid in d::type_attr_ids(bix) {
                let v = d::type_attr(bix, aid).unwrap();
                self.set_base(idx, aid, v);
            }
            for &aid in d::type_attr_ids(own_ty) {
                let v = d::type_attr(own_ty, aid).unwrap();
                self.set_base(idx, aid, v);
            }
            let own: Vec<usize> = self.items[idx].effects().map(|x| x.0).collect();
            for &x in d::type_effects(bix) {
                if !own.contains(&((x >> 1) as usize)) {
                    self.items[idx].extra_effs.push(x);
                }
            }
            if self.items[idx].req_skills.is_empty() {
                self.items[idx].req_skills = d::type_req_skills(bix);
            }
            if self.base_opt(idx, a::mass).unwrap_or(0.0) == 0.0 && d::type_mass(bix) != 0.0 {
                self.set_base(idx, a::mass, d::type_mass(bix));
            }
        }
        let muta = m.mutaplasmid_type_id.and_then(d::muta_attrs);
        let base_t = d::type_index(m.base_type_id);
        for (k, v) in &m.attributes {
            let Ok(aid) = k.parse::<u16>() else { continue };
            let mut val = *v;
            if let (Some(mu), Some(bt)) = (muta, base_t) {
                if let (Some(&(_, lo, hi)), Some(bv)) = (mu.iter().find(|x| x.0 == aid), d::type_attr(bt, aid)) {
                    let (x, y) = (bv * lo, bv * hi);
                    let (mn, mx) = if x < y { (x, y) } else { (y, x) };
                    if bv != 0.0 {
                        val = val.clamp(mn, mx);
                    }
                }
            }
            self.set_base(idx, aid, val);
        }
    }

    fn add_module(&mut self, i: usize, m: &ModuleReq, path: &str) -> Result<usize, EngineError> {
        let idx = self.new_item(m.type_id, Kind::Module, Loc::Ship, path)?;
        let slot = m.slot.or_else(|| infer_slot(self.items[idx].ty));
        let it = &mut self.items[idx];
        it.slot = slot;
        it.req_index = Some(i);
        it.spool = m.spool;
        it.state = m.state.unwrap_or(State::Online);
        if matches!(slot, Some(Slot::Rig) | Some(Slot::Subsystem)) && it.state != State::Offline {
            it.state = State::Online;
        }
        if let Some(mu) = &m.mutation {
            self.apply_mutation(idx, mu);
        }
        // Pyfa Module.isValidState: active needs an activatable effect (and no activationBlocked), overheated an
        // overload effect; an invalid state falls back to online (as the Pyfa oracle does).
        {
            let it = &self.items[idx];
            let st = it.state;
            if st >= State::Active {
                let can_active = it.effects().any(|(ei, _)| matches!(d::EFF_META[ei].cat, 1 | 2))
                    && d::type_attr(it.ty, a::activationBlocked).unwrap_or(0.0) <= 0.0;
                let can_heat = it.effects().any(|(ei, _)| d::EFF_META[ei].cat == 5);
                if !can_active || (st == State::Overheated && !can_heat) {
                    let msg = format!("{path}: state '{}' not possible for this module, using online", state_name(st));
                    self.items[idx].state = State::Online;
                    self.warnings.push(msg);
                }
            }
        }
        if let Some(c) = m.charge_type_id {
            let cidx = self.new_item(c, Kind::Charge, Loc::Ship, &format!("{path}/charge_type_id"))?;
            self.items[cidx].parent = Some(idx);
            self.items[cidx].req_index = Some(i);
            self.items[idx].charge = Some(cidx);
        }
        Ok(idx)
    }

    pub fn build(req: &FitRequest) -> Result<Fit, EngineError> {
        let mut fit = Fit {
            items: Vec::with_capacity(700),
            slots: Vec::with_capacity(2048),
            mods: Vec::with_capacity(4096),
            ship: 0,
            char: 0,
            warnings: Vec::new(),
            is_structure: false,
            ship_items: Vec::new(),
            char_items: Vec::new(),
            by_group: Vec::new(),
            by_skill: Vec::new(),
            skill_levels: Vec::new(),
            restrict: false,
            folded: Vec::with_capacity(d::PUBLISHED_SKILLS.len()),
            ext: Vec::new(),
            rr: Vec::new(),
            ext_drains: Vec::new(),
            ext_ecm: Vec::new(),
            props: Vec::new(),
        };
        let ship = fit.new_item(req.ship.type_id, Kind::Ship, Loc::Ship, "/ship/type_id")?;
        fit.ship = ship;
        fit.is_structure = fit.items[ship].category == 65;
        let ch = fit.new_item(d::T_CHARACTER, Kind::Char, Loc::Char, "/character")?;
        fit.char = ch;
        if let Some(sec) = req.character.security_status {
            fit.set_base(ch, a::pilotSecurityStatus, sec);
        }
        // skills: every published skill exists (untrained = level 0); overrides by id or name
        let default_level = req.character.skills.default_level.unwrap_or(0);
        let mut levels: Vec<(u32, u8)> = d::PUBLISHED_SKILLS.iter().map(|s| (*s, default_level)).collect();
        for (k, v) in &req.character.skills.levels {
            let id = k.parse::<u32>().ok().or_else(|| d::type_by_name(k));
            if let Some(id) = id {
                match levels.binary_search_by_key(&id, |x| x.0) {
                    Ok(p) => levels[p].1 = *v,
                    Err(p) => levels.insert(p, (id, *v)),
                }
            }
        }
        for &(s, l) in &levels {
            if d::type_index(s).is_none() {
                continue;
            }
            // fast path: published skill without attribute overrides -> compiled, level-folded modifiers
            if let Ok(k) = d::PUBLISHED_SKILLS.binary_search(&s) {
                if !req.overrides.iter().any(|o| o.type_id == s) {
                    fit.folded.push((k as u16, l.min(5)));
                    continue;
                }
            }
            let idx = fit.new_item(s, Kind::Skill, Loc::Char, "/character/skills")?;
            fit.set_base(idx, ATTR_SKILL_LEVEL, l.min(5) as f64);
            fit.items[idx].owned = false;
        }
        fit.skill_levels = levels;
        // T3D: default mode resolved at build time (lowest mode type id named after the hull)
        let mode_id = req.ship.mode_type_id.or_else(|| {
            let m = d::default_mode(req.ship.type_id)?;
            fit.warnings.push(format!("no tactical mode given; defaulted to type {m}"));
            Some(m)
        });
        if let Some(mode) = mode_id {
            let idx = fit.new_item(mode, Kind::Mode, Loc::Nowhere, "/ship/mode_type_id")?;
            fit.items[idx].owned = false;
        }
        for (i, m) in req.modules.iter().enumerate() {
            fit.add_module(i, m, &format!("/modules/{i}"))?;
        }
        for (i, dr) in req.drones.iter().enumerate() {
            let idx = fit.new_item(dr.type_id, Kind::Drone, Loc::Space, &format!("/drones/{i}"))?;
            if let Some(mu) = &dr.mutation {
                fit.apply_mutation(idx, mu);
            }
            let it = &mut fit.items[idx];
            it.quantity = dr.quantity.max(1);
            it.active_count = dr.active.unwrap_or(0).min(it.quantity);
            it.state = if it.active_count > 0 { State::Active } else { State::Offline };
            it.req_index = Some(i);
        }
        for (i, f) in req.fighters.iter().enumerate() {
            let idx = fit.new_item(f.type_id, Kind::Fighter, Loc::Space, &format!("/fighters/{i}"))?;
            let maxsq = fit.base_opt(idx, a::fighterSquadronMaxSize).map(|v| v as u32).unwrap_or(1);
            if f.quantity.unwrap_or(0) > maxsq {
                fit.warnings.push(format!("fighters/{i}: squadron size {} capped to {maxsq}", f.quantity.unwrap_or(0)));
            }
            let it = &mut fit.items[idx];
            it.quantity = f.quantity.unwrap_or(maxsq).clamp(1, maxsq.max(1));
            it.active_count = if f.active { it.quantity } else { 0 };
            it.state = if f.active { State::Active } else { State::Offline };
            it.fighter_abilities = f.abilities.clone().unwrap_or_else(|| d::fighter_default_abilities(f.type_id).to_vec());
            it.req_index = Some(i);
        }
        for (i, imp) in req.implants.iter().enumerate() {
            let idx = fit.new_item(*imp, Kind::Implant, Loc::Char, &format!("/implants/{i}"))?;
            fit.items[idx].owned = false;
            fit.items[idx].req_index = Some(i);
        }
        for (i, b) in req.boosters.iter().enumerate() {
            let idx = fit.new_item(b.type_id, Kind::Booster, Loc::Char, &format!("/boosters/{i}"))?;
            fit.items[idx].owned = false;
            fit.items[idx].booster_side_effects = b.side_effects.clone();
            fit.items[idx].req_index = Some(i);
        }
        for (i, x) in req.environment.effect_type_ids.iter().enumerate() {
            let idx = fit.new_item(*x, Kind::Beacon, Loc::Nowhere, &format!("/environment/effect_type_ids/{i}"))?;
            fit.items[idx].owned = false;
        }
        for (i, p) in req.projected.iter().enumerate() {
            match p.kind.as_str() {
                "module" => {
                    if let Some(m) = &p.module {
                        for _ in 0..p.amount.max(1) {
                            let idx = fit.new_item(m.type_id, Kind::Projected, Loc::Nowhere, &format!("/projected/{i}"))?;
                            let it = &mut fit.items[idx];
                            it.owned = false;
                            it.state = m.state.unwrap_or(State::Active);
                            it.distance = p.distance_m;
                            it.req_index = Some(i);
                            if let Some(c) = m.charge_type_id {
                                let cidx = fit.new_item(c, Kind::Charge, Loc::Nowhere, &format!("/projected/{i}/module/charge_type_id"))?;
                                fit.items[cidx].parent = Some(idx);
                                fit.items[cidx].owned = false;
                                fit.items[idx].charge = Some(cidx);
                            }
                        }
                    }
                }
                "drone" => {
                    if let Some(dr) = &p.drone {
                        for _ in 0..(p.amount.max(1) * dr.quantity.max(1)) {
                            let idx = fit.new_item(dr.type_id, Kind::Projected, Loc::Nowhere, &format!("/projected/{i}"))?;
                            let it = &mut fit.items[idx];
                            it.owned = false;
                            it.state = State::Active;
                            it.distance = p.distance_m;
                        }
                    }
                }
                "fighter" => {
                    if let Some(f) = &p.fighter {
                        for _ in 0..p.amount.max(1) {
                            let idx = fit.new_item(f.type_id, Kind::Projected, Loc::Nowhere, &format!("/projected/{i}"))?;
                            let maxsq = fit.base_opt(idx, a::fighterSquadronMaxSize).map(|v| v as u32).unwrap_or(1).max(1);
                            let it = &mut fit.items[idx];
                            it.owned = false;
                            it.state = if f.active { State::Active } else { State::Offline };
                            it.quantity = f.quantity.unwrap_or(maxsq).clamp(1, maxsq);
                            it.active_count = it.quantity;
                            it.distance = p.distance_m;
                            it.req_index = Some(i);
                            it.fighter_abilities = f.abilities.clone().unwrap_or_else(|| d::fighter_default_abilities(f.type_id).to_vec());
                        }
                    }
                }
                "fit" => {
                    if let Some(pf) = &p.fit {
                        let mut sub = (**pf).clone();
                        sub.projected.clear();
                        match Fit::build(&sub) {
                            Ok(sf) => fit.ext.push((sf, p.amount.max(1), p.distance_m)),
                            Err(e) => {
                                return Err(EngineError { code: e.code, message: e.message, path: format!("/projected/{i}/fit{}", e.path) });
                            }
                        }
                    }
                }
                other => fit.warnings.push(format!("projected kind '{other}' not supported yet (index {i})")),
            }
        }
        // system security -> securityModifier (default nullsec, like Pyfa)
        {
            let sec = req.environment.system_security.as_deref().unwrap_or("nullsec").to_lowercase();
            let src = match sec.as_str() {
                "hisec" | "highsec" | "high" => a::hiSecModifier,
                "lowsec" | "low" => a::lowSecModifier,
                "nullsec" | "null" | "wspace" | "wormhole" | "w-space" => a::nullSecModifier,
                other => {
                    fit.warnings.push(format!("unknown system_security '{other}', using nullsec"));
                    a::nullSecModifier
                }
            };
            for i in 0..fit.items.len() {
                if d::ty(fit.items[i].ty).flags & 2 != 0 || !fit.items[i].dyn_attrs.is_empty() {
                    if let Some(v) = fit.base_opt(i, src) {
                        fit.set_base(i, a::securityModifier, v);
                    }
                }
            }
        }
        for o in &req.overrides {
            for i in 0..fit.items.len() {
                if fit.items[i].type_id == o.type_id {
                    fit.set_base(i, o.attribute_id as u16, o.value);
                }
            }
        }
        fit.index();
        fit.register_all(req);
        fit.apply_rah(req);
        Ok(fit)
    }

    fn index(&mut self) {
        for (i, it) in self.items.iter().enumerate() {
            match it.loc {
                Loc::Ship => self.ship_items.push(i as u32),
                Loc::Char => self.char_items.push(i as u32),
                _ => {}
            }
            self.by_group.push((it.group, i as u32));
            if it.kind != Kind::Skill {
                for s in it.req_skills {
                    self.by_skill.push((*s, i as u32));
                }
            }
        }
        self.by_group.sort_unstable();
        self.by_skill.sort_unstable();
    }

    fn effective_state(&self, i: usize) -> State {
        let it = &self.items[i];
        match it.kind {
            Kind::Charge => it.parent.map(|p| self.items[p].state).unwrap_or(State::Online),
            Kind::Ship | Kind::Char | Kind::Skill | Kind::Implant | Kind::Booster | Kind::Mode | Kind::Beacon => State::Online,
            Kind::Drone | Kind::Fighter => {
                if it.active_count > 0 {
                    State::Active
                } else {
                    State::Offline
                }
            }
            _ => it.state,
        }
    }

    fn register_all(&mut self, req: &FitRequest) {
        let n = self.items.len();
        let is_structure = self.is_structure;
        for i in 0..n {
            if i == 2 {
                self.apply_folded_skills();
            }
            let kind = self.items[i].kind;
            if kind == Kind::Projected {
                continue;
            }
            // charges of projected modules (scripts) only act on their module
            let restricted = kind == Kind::Charge && self.items[i].loc == Loc::Nowhere;
            if is_structure && matches!(kind, Kind::Drone | Kind::Implant | Kind::Booster) {
                continue;
            }
            let state = self.effective_state(i);
            let src_cat = self.items[i].category;
            let p = !EXEMPT_CATEGORIES.contains(&src_cat);
            let n_static = self.items[i].effs.len();
            let n_extra = self.items[i].extra_effs.len();
            for k in 0..n_static + n_extra {
                let x = if k < n_static { self.items[i].effs[k] } else { self.items[i].extra_effs[k - n_static] };
                let ei = (x >> 1) as usize;
                let meta = &d::EFF_META[ei];
                let eid = d::EFF_IDS[ei];
                if is_structure && kind == Kind::Skill && meta.flags & 2 == 0 && !STRUCTURE_SKILL_EFFECTS.contains(&eid) {
                    continue;
                }
                if meta.flags & 1 != 0 && !self.items[i].booster_side_effects.contains(&eid) {
                    continue;
                }
                if kind == Kind::Fighter && meta.cat != 0 && !self.items[i].fighter_abilities.contains(&eid) {
                    continue;
                }
                if !state_ok(meta.cat, state) {
                    continue;
                }
                if restricted {
                    self.restrict = true;
                    d::apply_local(self, ei as u16, i, p);
                    self.restrict = false;
                } else {
                    d::apply_local(self, ei as u16, i, p);
                }
                if kind == Kind::Fighter && meta.flags & 8 != 0 {
                    self.fighter_self_ability(i, eid, p);
                }
            }
        }
        self.register_projectors(req);
        if n <= 2 {
            self.apply_folded_skills();
        }
        self.register_buffs(req);
    }

    /// Fighter self abilities have no modifier data in the SDE (Pyfa hand-written handlers): compiled here.
    fn fighter_self_ability(&mut self, i: usize, eid: u32, p: bool) {
        let list: &[(u16, u16, i8)] = match eid {
            e::fighterAbilityMicroWarpDrive => &[
                (a::maxVelocity, a::fighterAbilityMicroWarpDriveSpeedBonus, 6),
                (a::signatureRadius, a::fighterAbilityMicroWarpDriveSignatureRadiusBonus, 6),
            ],
            e::fighterAbilityAfterburner => &[(a::maxVelocity, a::fighterAbilityAfterburnerSpeedBonus, 6)],
            e::fighterAbilityEvasiveManeuvers => &[
                (a::maxVelocity, a::fighterAbilityEvasiveManeuversSpeedBonus, 6),
                (a::signatureRadius, a::fighterAbilityEvasiveManeuversSignatureRadiusBonus, 6),
                (a::shieldEmDamageResonance, a::fighterAbilityEvasiveManeuversEmResonance, 4),
                (a::shieldThermalDamageResonance, a::fighterAbilityEvasiveManeuversThermResonance, 4),
                (a::shieldKineticDamageResonance, a::fighterAbilityEvasiveManeuversKinResonance, 4),
                (a::shieldExplosiveDamageResonance, a::fighterAbilityEvasiveManeuversExpResonance, 4),
            ],
            _ => return,
        };
        for &(t, s, op) in list {
            self.push(i, t, op, p && !d::attr_stackable(t), Src::Attr { item: i as u32, attr: s });
        }
    }

    fn apply_folded_skills(&mut self) {
        let folded = std::mem::take(&mut self.folded);
        for &(k, l) in &folded {
            d::apply_skill(self, k as usize, l as usize);
        }
        self.folded = folded;
    }

    /// Resistance multiplier of this ship against a projected effect (Pyfa: missing or 0 -> 1).
    pub fn resist(&self, attr: u16) -> f64 {
        if attr == 0 {
            return 1.0;
        }
        let v = self.get(self.ship, attr);
        if v == 0.0 { 1.0 } else { v }
    }

    fn register_projectors(&mut self, req: &FitRequest) {
        let _ = req;
        let mut acts: Vec<ProjAction> = Vec::new();
        for i in 0..self.items.len() {
            if self.items[i].kind == Kind::Projected && self.items[i].state >= State::Active {
                let dist = self.items[i].distance;
                collect_projection(self, i, dist, 1, &mut acts);
            }
        }
        for (sf, amount, dist) in &self.ext {
            for i in 0..sf.items.len() {
                let it = &sf.items[i];
                match it.kind {
                    Kind::Module if it.state >= State::Active => collect_projection(sf, i, *dist, *amount, &mut acts),
                    // Pyfa projects a fit's drones at range 0
                    Kind::Drone if it.active_count > 0 => collect_projection(sf, i, Some(0.0), *amount * it.active_count, &mut acts),
                    Kind::Fighter if it.active_count > 0 => collect_projection(sf, i, *dist, *amount, &mut acts),
                    _ => {}
                }
            }
        }
        let ship = self.ship;
        let no_offense = self.base(ship, a::disallowOffensiveModifiers) != 0.0;
        let no_assist = self.get(ship, a::disallowAssistance) != 0.0;
        for a in acts {
            match a {
                ProjAction::Mod { off: true, .. } if no_offense => {}
                ProjAction::Ecm { .. } if no_offense => {}
                ProjAction::ModItems { assist: false, .. } if no_offense => {}
                ProjAction::ModItems { assist: true, .. } if no_assist => {}
                ProjAction::Mod { attr, op, v, factor, resist, pen, .. } => {
                    let mul = op == 4 || op == 0;
                    self.push(ship, attr, op, pen, Src::Projected { v, factor, resist, mul });
                }
                ProjAction::ModItems { skill, charge, attr, v, factor, resist, .. } => {
                    for m in 0..self.items.len() {
                        if self.items[m].kind != Kind::Module || self.items[m].loc != Loc::Ship {
                            continue;
                        }
                        let t = if charge { match self.items[m].charge { Some(c) => c, None => continue } } else { m };
                        if self.items[t].req_skills.contains(&skill) {
                            self.push(t, attr, 6, true, Src::Projected { v, factor, resist, mul: false });
                        }
                    }
                }
                ProjAction::Rr { kind, amount, dur_s } => self.rr.push((kind, amount, dur_s)),
                ProjAction::Drain(dr) => self.ext_drains.push(dr),
                ProjAction::Ecm { st, resist } => self.ext_ecm.push(ExtEcm { st, resist }),
                ProjAction::Warn(w) => {
                    if !self.warnings.contains(&w) {
                        self.warnings.push(w)
                    }
                }
            }
        }
        self.clear_cache();
    }

    fn register_buffs(&mut self, req: &FitRequest) {
        let mut agg: Vec<(u32, f64)> = Vec::new();
        for b in &req.fleet.buffs {
            if !d::dbuff_exists(b.buff_id) {
                self.warnings.push(format!("unknown warfare buff {}", b.buff_id));
                continue;
            }
            match agg.iter_mut().find(|x| x.0 == b.buff_id) {
                Some(x) => x.1 = if d::dbuff_min_aggregate(b.buff_id) { x.1.min(b.value) } else { x.1.max(b.value) },
                None => agg.push((b.buff_id, b.value)),
            }
        }
        agg.sort_by_key(|x| x.0);
        let ship = self.ship;
        for (id, value) in agg {
            self.apply_buff(id, Src::Const(value), ship);
        }
        let explicit: Vec<u32> = req.fleet.buffs.iter().map(|b| b.buff_id).collect();
        if req.fleet.booster_fits.is_empty() {
            // local command bursts: per buff id only the strongest burst (by |value|) applies (Pyfa); its value
            // is read (lazily) from the module
            let mut best: Vec<(u32, usize, u16, f64)> = Vec::new();
            for i in 0..self.items.len() {
                if self.items[i].kind != Kind::Module || self.items[i].state < State::Active {
                    continue;
                }
                for (ida, vala) in BUFF_PAIRS {
                    let id = if self.has(i, ida) { self.get(i, ida) as u32 } else { 0 };
                    if id == 0 || explicit.contains(&id) {
                        continue;
                    }
                    let v = self.get(i, vala).abs();
                    match best.iter_mut().find(|x| x.0 == id) {
                        Some(x) => {
                            if x.3 < v {
                                *x = (id, i, vala, v);
                            }
                        }
                        None => best.push((id, i, vala, v)),
                    }
                }
            }
            for (id, i, vala) in self.beacon_buffs() {
                if explicit.contains(&id) {
                    continue;
                }
                let v = self.get(i, vala).abs();
                match best.iter_mut().find(|x| x.0 == id) {
                    Some(x) => {
                        if x.3 < v {
                            *x = (id, i, vala, v);
                        }
                    }
                    None => best.push((id, i, vala, v)),
                }
            }
            self.clear_cache();
            for (id, i, vala, _) in best {
                self.apply_buff(id, Src::Attr { item: i as u32, attr: vala }, i);
            }
            self.clear_cache();
            return;
        }
        // fleet boosters: like Pyfa, every buff id keeps the strongest value (by magnitude) over this fit's own
        // bursts and all booster fits' bursts, and is applied once.
        let mut best: Vec<(u32, f64)> = self.burst_values();
        for (id, i, vala) in self.beacon_buffs() {
            let v = self.get(i, vala);
            match best.iter_mut().find(|x| x.0 == id) {
                Some(x) => {
                    if x.1.abs() < v.abs() {
                        x.1 = v
                    }
                }
                None => best.push((id, v)),
            }
        }
        self.clear_cache();
        for (k, bf) in req.fleet.booster_fits.iter().enumerate() {
            match Fit::build(bf) {
                Ok(b) => {
                    for (id, v) in b.burst_values() {
                        match best.iter_mut().find(|x| x.0 == id) {
                            Some(x) => {
                                if x.1.abs() < v.abs() {
                                    x.1 = v
                                }
                            }
                            None => best.push((id, v)),
                        }
                    }
                }
                Err(e) => self.warnings.push(format!("fleet/booster_fits/{k}: {} {}", e.code, e.message)),
            }
        }
        best.sort_by_key(|x| x.0);
        for (id, v) in best {
            if !explicit.contains(&id) {
                self.apply_buff(id, Src::Const(v), ship);
            }
        }
    }

    /// (buff id, value) of every active command burst on this fit, strongest per id.
    pub fn burst_values(&self) -> Vec<(u32, f64)> {
        let mut out: Vec<(u32, f64)> = Vec::new();
        for i in 0..self.items.len() {
            if self.items[i].kind != Kind::Module || self.items[i].state < State::Active {
                continue;
            }
            for (ida, vala) in BUFF_PAIRS {
                let id = if self.has(i, ida) { self.get(i, ida) as u32 } else { 0 };
                if id == 0 {
                    continue;
                }
                let v = self.get(i, vala);
                match out.iter_mut().find(|x| x.0 == id) {
                    Some(x) => {
                        if x.1.abs() < v.abs() {
                            x.1 = v
                        }
                    }
                    None => out.push((id, v)),
                }
            }
        }
        out
    }

    fn clear_cache(&self) {
        for s in &self.slots {
            s.st.set(0);
        }
    }

    /// Reactive Armor Hardener adaptation (no modifierInfo in the SDE): simulate cycles against the incoming
    /// damage pattern, average the loop, apply as a penalised PreMul (behaviour of Pyfa/eos, via eve-dogma-rs).
    fn apply_rah(&mut self, req: &FitRequest) {
        let attrs = [a::armorEmDamageResonance, a::armorThermalDamageResonance, a::armorKineticDamageResonance, a::armorExplosiveDamageResonance];
        let rahs: Vec<usize> = (0..self.items.len())
            .filter(|&i| {
                self.items[i].kind == Kind::Module && self.items[i].state >= State::Active && self.items[i].has_effect(e::adaptiveArmorHardener)
            })
            .collect();
        if rahs.is_empty() {
            return;
        }
        let disable = req.options.rah.as_deref() == Some("disable");
        let dp = req.damage_pattern.unwrap_or(crate::request::Resists { em: 25.0, thermal: 25.0, kinetic: 25.0, explosive: 25.0 });
        let pattern = [dp.em, dp.thermal, dp.kinetic, dp.explosive];
        let ship = self.ship;
        for m in rahs {
            self.clear_cache();
            let mut res: [f64; 4] = [0.0; 4];
            for k in 0..4 {
                res[k] = self.get(m, attrs[k]);
            }
            if !disable {
                let base: Vec<f64> = (0..4).map(|k| pattern[k] * self.get(ship, attrs[k])).collect();
                let shift = self.get(m, a::resistanceShiftAmount) / 100.0;
                let mut cycles: Vec<[f64; 4]> = Vec::new();
                let mut loop_start: isize = -20;
                for _ in 0..50 {
                    // in-game tie order em, explosive, kinetic, thermal
                    let mut t: Vec<(usize, f64, f64)> = [0usize, 3, 2, 1].iter().map(|&k| (k, base[k] * res[k], res[k])).collect();
                    t.sort_by(|x, y| x.1.partial_cmp(&y.1).unwrap_or(std::cmp::Ordering::Equal));
                    let (c0, c1, c2, c3);
                    if t[2].1 == 0.0 {
                        c0 = 1.0 - t[0].2;
                        c1 = 1.0 - t[1].2;
                        c2 = 1.0 - t[2].2;
                        c3 = -(c0 + c1 + c2);
                    } else if t[1].1 == 0.0 {
                        c0 = 1.0 - t[0].2;
                        c1 = 1.0 - t[1].2;
                        c2 = -(c0 + c1) / 2.0;
                        c3 = c2;
                    } else {
                        c0 = shift.min(1.0 - t[0].2);
                        c1 = shift.min(1.0 - t[1].2);
                        c2 = -(c0 + c1) / 2.0;
                        c3 = c2;
                    }
                    res[t[0].0] = t[0].2 + c0;
                    res[t[1].0] = t[1].2 + c1;
                    res[t[2].0] = t[2].2 + c2;
                    res[t[3].0] = t[3].2 + c3;
                    if let Some(i) = cycles.iter().position(|v| (0..4).all(|k| (res[k] - v[k]).abs() <= 1e-6)) {
                        loop_start = i as isize;
                        break;
                    }
                    cycles.push(res);
                }
                let start = if loop_start >= 0 { loop_start as usize } else { cycles.len().saturating_sub(20) };
                let lp = &cycles[start..];
                if !lp.is_empty() {
                    for k in 0..4 {
                        res[k] = crate::stats::py_round(lp.iter().map(|v| v[k]).sum::<f64>() / lp.len() as f64, 3);
                    }
                }
            }
            let p = !EXEMPT_CATEGORIES.contains(&self.items[m].category);
            for k in 0..4 {
                let pen = p && !d::attr_stackable(attrs[k]);
                if !disable {
                    self.push(m, attrs[k], 7, pen, Src::Const(res[k]));
                }
                self.push(ship, attrs[k], 0, pen, Src::Const(res[k]));
            }
        }
        self.clear_cache();
    }

    // ------------------------------------------------------------ evaluation
    #[inline]
    pub fn get(&self, i: usize, attr: u16) -> f64 {
        match self.slot_of(i, attr) {
            Some(s) => self.eval(i, attr, s as usize),
            None => match d::type_attr(self.items[i].ty, attr) {
                Some(v) => self.post(i, attr, v),
                None => d::attr_default(attr),
            },
        }
    }

    pub fn get_opt(&self, i: usize, attr: u16) -> Option<f64> {
        if self.has(i, attr) { Some(self.get(i, attr)) } else { None }
    }

    /// min/max caps and fitting rounding (applied to every present attribute, modified or not)
    #[inline]
    fn post(&self, i: usize, attr: u16, mut val: f64) -> f64 {
        let ix = attr as usize;
        if ix >= d::ATTR_COUNT {
            return val;
        }
        let mn = d::ATTR_MIN[ix];
        if mn != 0 {
            val = val.max(self.get(i, mn));
        }
        let mx = d::ATTR_MAX[ix];
        if mx != 0 {
            val = val.min(self.get(i, mx));
        }
        if d::ATTR_FLAGS[ix] & d::AF_ROUND2 != 0 {
            val = crate::stats::py_round(val, 2);
        }
        val
    }

    fn src_value(&self, s: &Src) -> f64 {
        match *s {
            Src::Attr { item, attr } => {
                if d::attr_flags(attr) & d::AF_OVERLOAD != 0 && self.items[item as usize].kind == Kind::Module {
                    self.eval_before(item as usize, attr)
                } else {
                    self.get(item as usize, attr)
                }
            }
            Src::Const(v) => v,
            Src::Prop { module } => {
                let mut m = self.get(self.ship, a::mass);
                for &j in &self.props {
                    if j > module {
                        m -= self.get(j as usize, a::massAddition);
                    }
                }
                if m == 0.0 {
                    1.0
                } else {
                    1.0 + self.get(module as usize, a::speedFactor) / 100.0 * self.get(module as usize, a::speedBoostFactor) / m
                }
            }
            Src::Projected { v, factor, resist, mul } => {
                let f = factor * self.resist(resist);
                if mul { (v - 1.0) * f + 1.0 } else { v * f }
            }
        }
    }

    /// Pyfa evaluates effects module by module: an overheat effect reads its module's `overload*` attribute before
    /// modules later in the fit have applied their modifiers (e.g. a Tengu defensive subsystem listed after the
    /// hardener does not boost overloadHardeningBonus yet). Value of (i, attr) ignoring modifiers whose source is
    /// a module after `i`.
    /// ship signatureRadius without the MWD bloom: Pyfa's MWD handler runs 'late', after the 'normal'-runtime
    /// projected neutralisers read the target's signature radius
    pub fn sig_before_late(&self) -> f64 {
        let (i, attr) = (self.ship, a::signatureRadius);
        let Some(s) = self.slot_of(i, attr).map(|s| s as usize) else { return self.get(i, attr) };
        let slot = &self.slots[s];
        let mut vals: Vec<(i8, bool, f64)> = Vec::new();
        let mut present = 0u16;
        let mut skipped = false;
        let mut cur = slot.head;
        for _ in 0..slot.n {
            let (m, next) = &self.mods[cur as usize];
            cur = *next;
            if let Src::Attr { item, attr: sa } = m.src {
                if sa == a::signatureRadiusBonus && self.props.contains(&item) {
                    skipped = true;
                    continue;
                }
            }
            vals.push((m.op, m.pen, self.src_value(&m.src)));
            present |= 1 << ((m.op + 1) as u16 & 15);
        }
        if !skipped {
            return self.get(i, attr);
        }
        let hig = d::attr_flags(attr) & d::AF_HIGH_IS_GOOD != 0 || d::attr_flags(attr) & 1 == 0;
        let val = combine(slot.base, hig, &vals, present);
        self.post(i, attr, val)
    }
    fn eval_before(&self, i: usize, attr: u16) -> f64 {
        let Some(s) = self.slot_of(i, attr).map(|s| s as usize) else { return self.get(i, attr) };
        let slot = &self.slots[s];
        let mut vals: Vec<(i8, bool, f64)> = Vec::new();
        let mut present = 0u16;
        let mut skipped = false;
        let mut cur = slot.head;
        for _ in 0..slot.n {
            let (m, next) = &self.mods[cur as usize];
            cur = *next;
            let src_item = match m.src {
                Src::Attr { item, .. } => Some(item as usize),
                Src::Prop { module } => Some(module as usize),
                _ => None,
            };
            if let Some(si) = src_item {
                if si > i && self.items[si].kind == Kind::Module && self.items[si].loc == Loc::Ship {
                    skipped = true;
                    continue;
                }
            }
            vals.push((m.op, m.pen, self.src_value(&m.src)));
            present |= 1 << ((m.op + 1) as u16 & 15);
        }
        if !skipped {
            return self.get(i, attr);
        }
        let hig = d::attr_flags(attr) & d::AF_HIGH_IS_GOOD != 0 || d::attr_flags(attr) & 1 == 0;
        let val = combine(slot.base, hig, &vals, present);
        self.post(i, attr, val)
    }

    fn eval(&self, i: usize, attr: u16, s: usize) -> f64 {
        let slot = &self.slots[s];
        match slot.st.get() {
            2 => return slot.val.get(),
            1 => return slot.base,
            _ => {}
        }
        slot.st.set(1);
        let mut val = slot.base;
        let n = slot.n as usize;
        if n > 0 {
            let hig = d::attr_flags(attr) & d::AF_HIGH_IS_GOOD != 0 || d::attr_flags(attr) & 1 == 0;
            // resolve source values once; bucket by operator (op -1..7 -> 0..8)
            let mut buf_small = [(0i8, false, 0f64); 32];
            let mut buf_big: Vec<(i8, bool, f64)> = Vec::new();
            let vals: &mut [(i8, bool, f64)] = if n <= 32 {
                &mut buf_small[..n]
            } else {
                buf_big.resize(n, (0, false, 0.0));
                &mut buf_big[..]
            };
            let mut present = 0u16;
            let mut cur = slot.head;
            for k in 0..n {
                let (m, next) = &self.mods[cur as usize];
                cur = *next;
                vals[k] = (m.op, m.pen, self.src_value(&m.src));
                present |= 1 << ((m.op + 1) as u16 & 15);
            }
            val = combine(val, hig, vals, present);
        }
        let val = self.post(i, attr, val);
        slot.st.set(2);
        slot.val.set(val);
        val
    }
}

use crate::data::PENALTY;

/// Apply resolved modifiers (op, penalised, value) to `val` in dogma operator order (Pyfa-compatible float order).
/// op 8 = PostMul that Pyfa stacks in the "default" penalty group together with PostPercent boosts
/// (hand-written Pyfa effects calling multiplyItemAttr(..., stackingPenalties=True) without a group).
fn combine(mut val: f64, hig: bool, vals: &[(i8, bool, f64)], present: u16) -> f64 {
    let present = if present & (1 << 9) != 0 { present | (1 << 7) } else { present };
    // Pyfa folds every non-penalised post multiplier (postMul / postDiv / postPercent) into one product
    // and applies it once before the penalised ones (val * (m1 * m2)), which matters for float-exact
    // results that are later truncated (e.g. cap-sim cycle times).
    let mut post_mult = 1.0f64;
    let mut post_any = false;
    for &(o, pen, v) in vals.iter() {
        if !pen && ((4..=6).contains(&o) || o == 8) {
            post_mult *= match o {
                4 | 8 => v,
                5 => {
                    if v == 0.0 { 1.0 } else { 1.0 / v }
                }
                _ => 1.0 + v / 100.0,
            };
            post_any = true;
        }
    }
    for op in -1i8..=7 {
        if op == 4 && post_any {
            val *= post_mult;
        }
        if present & (1 << (op + 1)) == 0 {
            continue;
        }
        let mut assign: Option<f64> = None;
        let mut pos = [0f64; 32];
        let mut neg = [0f64; 32];
        let (mut np, mut nn) = (0usize, 0usize);
        let mut pos_v: Vec<f64> = Vec::new();
        let mut neg_v: Vec<f64> = Vec::new();
        for &(o, pen, v) in vals.iter() {
            if o != op && !(op == 6 && o == 8) {
                continue;
            }
            match op {
                -1 | 7 => {
                    assign = Some(match assign {
                        None => v,
                        Some(c) => {
                            if hig { c.max(v) } else { c.min(v) }
                        }
                    });
                }
                2 => val += v,
                3 => val -= v,
                _ => {
                    let m = match o {
                        0 | 4 | 8 => v,
                        1 | 5 => {
                            if v == 0.0 { 1.0 } else { 1.0 / v }
                        }
                        6 => 1.0 + v / 100.0,
                        _ => 1.0,
                    };
                    if pen {
                        if m > 1.0 {
                            if np < 32 { pos[np] = m; np += 1 } else { pos_v.push(m) }
                        } else if m < 1.0 {
                            if nn < 32 { neg[nn] = m; nn += 1 } else { neg_v.push(m) }
                        }
                    } else if op < 4 {
                        val *= m;
                    }
                }
            }
        }
        if let Some(v) = assign {
            val = v;
        }
        if np + nn > 0 {
            for (list, extra) in [(&mut pos[..np], &pos_v), (&mut neg[..nn], &neg_v)] {
                let mut l: Vec<f64>;
                let list: &mut [f64] = if extra.is_empty() {
                    list
                } else {
                    l = list.to_vec();
                    l.extend_from_slice(extra);
                    &mut l[..]
                };
                list.sort_by(|x, y| (y - 1.0).abs().partial_cmp(&(x - 1.0).abs()).unwrap_or(std::cmp::Ordering::Equal));
                for (k, m) in list.iter().enumerate() {
                    val *= 1.0 + (m - 1.0) * PENALTY[k.min(PENALTY.len() - 1)];
                }
            }
        }
    }
    val
}

/// Slot from the type's slot effect (hiPower 12, medPower 13, loPower 11, rigSlot 2663, subSystem 3772, serviceSlot 6306).
pub fn infer_slot(ty: usize) -> Option<Slot> {
    for &x in d::type_effects(ty) {
        match d::EFF_IDS[(x >> 1) as usize] {
            12 => return Some(Slot::High),
            13 => return Some(Slot::Mid),
            11 => return Some(Slot::Low),
            2663 => return Some(Slot::Rig),
            3772 => return Some(Slot::Subsystem),
            6306 => return Some(Slot::Service),
            _ => {}
        }
    }
    None
}

/// group id of "Missile Launcher Bomb"
const G_MISSILE_LAUNCHER_BOMB: u32 = 862;

/// Evaluate everything item `i` of fit `sf` projects (all values from the projecting side), `times` times.
fn collect_projection(sf: &Fit, i: usize, distance: Option<f64>, times: u32, out: &mut Vec<ProjAction>) {
    let g = |x: u16| sf.get(i, x);
    let pen_cat = !EXEMPT_CATEGORIES.contains(&sf.items[i].category);
    let effs: Vec<usize> = sf.items[i].effects().map(|x| x.0).collect();
    let paste = sf.items[i].charge.map(|c| sf.items[c].type_id == d::T_NANITE_REPAIR_PASTE).unwrap_or(false);
    let qty = sf.items[i].quantity.max(1) as f64;
    // the target never takes offensive modifiers (e.g. structures in some systems) -- checked by the caller's ship
    for ei in effs {
        let meta = d::EFF_META[ei];
        let eid = d::EFF_IDS[ei];
        let doomsday = matches!(
            eid,
            e::doomsdayAOEWeb | e::doomsdayAOENeut | e::doomsdayAOEPaint | e::doomsdayAOETrack | e::doomsdayAOEDamp | e::doomsdayAOEECM
        );
        // projected bomb launcher (Pyfa: launcher effect in 'projected' context, group Missile Launcher Bomb): a
        // void bomb neutralises energyNeutralizerAmount of the charge once per launcher speed + reactivation delay.
        // An input-side capacitor drain: no range factor, no resistance (Pyfa fit.addDrain).
        if eid == e::useMissiles && sf.items[i].group == G_MISSILE_LAUNCHER_BOMB {
            if let Some(c) = sf.items[i].charge {
                let delay = g(a::moduleReactivationDelay);
                let speed = g(a::speed);
                let neut = sf.get(c, a::energyNeutralizerAmount);
                if delay != 0.0 && neut != 0.0 && speed != 0.0 {
                    let dr = ExtDrain {
                        cycle_ms: speed + delay,
                        amount: neut,
                        resist: 0,
                        sig_res: g(a::energyNeutralizerSignatureResolution),
                        assistance: false,
                        late: false,
                    };
                    for _ in 0..times {
                        out.push(ProjAction::Drain(dr));
                    }
                }
                // lockbreaker bombs: ECM strength of the charge (Pyfa fit.addProjectedEcm, no resistance)
                const ECM_BOMB: [u16; 4] = [a::scanMagnetometricStrengthBonus, a::scanLadarStrengthBonus, a::scanRadarStrengthBonus, a::scanGravimetricStrengthBonus];
                let st = ECM_BOMB.map(|x| sf.get(c, x));
                if st.iter().any(|&v| v != 0.0) {
                    for _ in 0..times {
                        out.push(ProjAction::Ecm { st, resist: 0 });
                    }
                }
            }
            continue;
        }
        if meta.cat != 2 && meta.cat != 3 && eid != e::ECMBurstJammer && !doomsday {
            continue;
        }
        if meta.flags & 8 != 0 && !sf.items[i].fighter_abilities.contains(&eid) {
            continue;
        }
        let rf = |opt: u16, fo: u16| crate::stats::range_factor(g(opt), g(fo), distance, true);
        let resist = if meta.resist != 0 {
            meta.resist
        } else if meta.flags & 8 != 0 {
            // fighter abilities: "<effect>ResistanceID" attribute, if any
            if eid == e::fighterAbilityStasisWebifier { g(a::fighterAbilityStasisWebifierResistanceID) as u16 } else { 0 }
        } else {
            g(a::remoteResistanceID) as u16
        };
        let ecm = |base: [u16; 4], factor: f64| ProjAction::Ecm { st: [g(base[0]) * factor, g(base[1]) * factor, g(base[2]) * factor, g(base[3]) * factor], resist };
        const ECM_MOD: [u16; 4] = [a::scanMagnetometricStrengthBonus, a::scanLadarStrengthBonus, a::scanRadarStrengthBonus, a::scanGravimetricStrengthBonus];
        const ECM_FIGHTER: [u16; 4] = [
            a::fighterAbilityECMStrengthMagnetometric,
            a::fighterAbilityECMStrengthLadar,
            a::fighterAbilityECMStrengthRadar,
            a::fighterAbilityECMStrengthGravimetric,
        ];
        let cutoff = |attr: u16| distance.map(|dd| g(attr) < dd).unwrap_or(false);
        let mut one: Vec<ProjAction> = Vec::new();
        match eid {
            e::shipModuleRemoteArmorRepairer | e::shipModuleAncillaryRemoteArmorRepairer | e::ShipModuleRemoteArmorMutadaptiveRepairer => {
                let mult = if eid == e::shipModuleAncillaryRemoteArmorRepairer && paste { 3.0 } else { 1.0 };
                let mut amount = g(a::armorDamageAmount) * mult * rf(a::maxRange, a::falloffEffectiveness);
                let dur_s = g(a::duration) / 1000.0;
                if eid == e::ShipModuleRemoteArmorMutadaptiveRepairer {
                    let spool = sf.items[i].spool.unwrap_or(crate::request::Spool { kind: crate::request::SpoolType::SpoolScale, amount: 1.0 });
                    let (sp, _, _) = crate::stats::spoolup(g(a::repairMultiplierBonusMax), g(a::repairMultiplierBonusPerCycle), dur_s, spool);
                    amount *= 1.0 + sp;
                }
                one.push(ProjAction::Rr { kind: 1, amount, dur_s });
            }
            e::shipModuleRemoteShieldBooster | e::shipModuleAncillaryRemoteShieldBooster => {
                one.push(ProjAction::Rr { kind: 0, amount: g(a::shieldBonus) * rf(a::maxRange, a::falloffEffectiveness), dur_s: g(a::duration) / 1000.0 });
            }
            e::shipModuleRemoteHullRepairer => {
                one.push(ProjAction::Rr { kind: 2, amount: g(a::structureDamageAmount) * rf(a::maxRange, a::falloffEffectiveness), dur_s: g(a::duration) / 1000.0 });
            }
            e::npcEntityRemoteArmorRepairer | e::npcEntityRemoteShieldBooster | e::npcEntityRemoteHullRepairer => {
                if !cutoff(a::maxRange) {
                    let (kind, amt) = match eid {
                        e::npcEntityRemoteArmorRepairer => (1, g(a::armorDamageAmount)),
                        e::npcEntityRemoteShieldBooster => (0, g(a::shieldBonus)),
                        _ => (2, g(a::structureDamageAmount)),
                    };
                    one.push(ProjAction::Rr { kind, amount: amt, dur_s: g(a::duration) / 1000.0 });
                }
            }
            e::energyNeutralizerFalloff | e::structureEnergyNeutralizerFalloff => {
                let amount = g(a::energyNeutralizerAmount) * rf(a::maxRange, a::falloffEffectiveness);
                one.push(ProjAction::Drain(ExtDrain { cycle_ms: g(a::duration), amount, resist, sig_res: g(a::energyNeutralizerSignatureResolution), assistance: false, late: false }));
            }
            e::energyNosferatuFalloff => {
                let amount = g(a::powerTransferAmount) * rf(a::maxRange, a::falloffEffectiveness);
                one.push(ProjAction::Drain(ExtDrain { cycle_ms: g(a::duration), amount, resist, sig_res: g(a::energyNeutralizerSignatureResolution), assistance: false, late: true }));
            }
            e::shipModuleRemoteCapacitorTransmitter => {
                if !cutoff(a::maxRange) {
                    let amount = -g(a::powerTransferAmount);
                    one.push(ProjAction::Drain(ExtDrain { cycle_ms: g(a::duration), amount, resist, sig_res: g(a::energyNeutralizerSignatureResolution), assistance: true, late: false }));
                }
            }
            e::remoteECMFalloff | e::structureModuleEffectECM => one.push(ecm(ECM_MOD, rf(a::maxRange, a::falloffEffectiveness))),
            e::entityECMFalloff => one.push(ecm(ECM_MOD, if cutoff(a::ECMRangeOptimal) { 0.0 } else { 1.0 })),
            e::ECMBurstJammer => one.push(ecm(ECM_MOD, if cutoff(a::ecmBurstRange) { 0.0 } else { 1.0 })),
            e::fighterAbilityECM => {
                one.push(ecm(ECM_FIGHTER, rf(a::fighterAbilityECMRangeOptimal, a::fighterAbilityECMRangeFalloff) * qty));
            }
            e::fighterAbilityEnergyNeutralizer => {
                let amount = g(a::fighterAbilityEnergyNeutralizerAmount)
                    * rf(a::fighterAbilityEnergyNeutralizerOptimalRange, a::fighterAbilityEnergyNeutralizerFalloffRange)
                    * qty;
                one.push(ProjAction::Drain(ExtDrain {
                    cycle_ms: g(a::fighterAbilityEnergyNeutralizerDuration),
                    amount,
                    resist,
                    sig_res: 0.0,
                    assistance: false, late: false,
                }));
            }
            e::fighterAbilityStasisWebifier => {
                let f = rf(a::fighterAbilityStasisWebifierOptimalRange, a::fighterAbilityStasisWebifierFalloffRange) * qty;
                one.push(ProjAction::Mod { attr: a::maxVelocity, op: 6, v: g(a::fighterAbilityStasisWebifierSpeedPenalty), factor: f, resist, pen: pen_cat, off: true });
            }
            e::fighterAbilityWarpDisruption => {
                if g(a::fighterAbilityWarpDisruptionRange) >= distance.unwrap_or(0.0) {
                    one.push(ProjAction::Mod { attr: a::warpScrambleStatus, op: 2, v: g(a::fighterAbilityWarpDisruptionPointStrength), factor: qty, resist, pen: false, off: true });
                }
            }
            // titan burst projectors (Pyfa Effect6476..6513): full strength, no range factor
            e::doomsdayAOEWeb => one.push(ProjAction::Mod { attr: a::maxVelocity, op: 6, v: g(a::speedFactor), factor: 1.0, resist, pen: true, off: true }),
            e::doomsdayAOEPaint => {
                one.push(ProjAction::Mod { attr: a::signatureRadius, op: 6, v: g(a::signatureRadiusBonus), factor: 1.0, resist, pen: true, off: true })
            }
            e::doomsdayAOEDamp => {
                one.push(ProjAction::Mod { attr: a::maxTargetRange, op: 6, v: g(a::maxTargetRangeBonus), factor: 1.0, resist, pen: true, off: true });
                one.push(ProjAction::Mod { attr: a::scanResolution, op: 6, v: g(a::scanResolutionBonus), factor: 1.0, resist, pen: true, off: true });
            }
            e::doomsdayAOETrack => {
                for (src, tgt) in [
                    (a::aoeCloudSizeBonus, a::aoeCloudSize),
                    (a::aoeVelocityBonus, a::aoeVelocity),
                    (a::missileVelocityBonus, a::maxVelocity),
                    (a::explosionDelayBonus, a::explosionDelay),
                ] {
                    one.push(ProjAction::ModItems { skill: SKILL_MISSILE_LAUNCHER_OPERATION, charge: true, attr: tgt, v: g(src), factor: 1.0, resist, assist: false });
                }
                for (src, tgt) in [(a::trackingSpeedBonus, a::trackingSpeed), (a::maxRangeBonus, a::maxRange), (a::falloffBonus, a::falloff)] {
                    one.push(ProjAction::ModItems { skill: SKILL_GUNNERY, charge: false, attr: tgt, v: g(src), factor: 1.0, resist, assist: false });
                }
            }
            e::doomsdayAOENeut => {
                one.push(ProjAction::Drain(ExtDrain { cycle_ms: g(a::duration), amount: g(a::energyNeutralizerAmount), resist, sig_res: 0.0, assistance: false, late: false }));
            }
            e::doomsdayAOEECM => one.push(ecm(ECM_MOD, 1.0)),
            e::npcEntityWeaponDisruptor => {
                if !cutoff(a::maxRange) {
                    for (src, tgt) in [(a::trackingSpeedBonus, a::trackingSpeed), (a::maxRangeBonus, a::maxRange), (a::falloffBonus, a::falloff)] {
                        one.push(ProjAction::ModItems { skill: SKILL_GUNNERY, charge: false, attr: tgt, v: g(src), factor: 1.0, resist, assist: false });
                    }
                }
            }
            e::shipModuleRemoteTrackingComputer => {
                let f = rf(a::maxRange, a::falloffEffectiveness);
                for (src, tgt) in [(a::trackingSpeedBonus, a::trackingSpeed), (a::maxRangeBonus, a::maxRange), (a::falloffBonus, a::falloff)] {
                    one.push(ProjAction::ModItems { skill: SKILL_GUNNERY, charge: false, attr: tgt, v: g(src), factor: f, resist, assist: true });
                }
            }
            e::structureModuleEffectWeaponDisruption => {
                // Standup Weapon Disruptor: missile charges and turrets at once (Pyfa Effect6686)
                let f = rf(a::maxRange, a::falloffEffectiveness);
                for (src, tgt) in [(a::aoeCloudSizeBonus, a::aoeCloudSize), (a::aoeVelocityBonus, a::aoeVelocity), (a::missileVelocityBonus, a::maxVelocity), (a::explosionDelayBonus, a::explosionDelay)] {
                    one.push(ProjAction::ModItems { skill: SKILL_MISSILE_LAUNCHER_OPERATION, charge: true, attr: tgt, v: g(src), factor: f, resist, assist: false });
                }
                for (src, tgt) in [(a::trackingSpeedBonus, a::trackingSpeed), (a::maxRangeBonus, a::maxRange), (a::falloffBonus, a::falloff)] {
                    one.push(ProjAction::ModItems { skill: SKILL_GUNNERY, charge: false, attr: tgt, v: g(src), factor: f, resist, assist: false });
                }
            }
            e::shipModuleTrackingDisruptor | e::shipModuleGuidanceDisruptor => {
                let f = rf(a::maxRange, a::falloffEffectiveness);
                let (skill, charge, pairs): (u32, bool, &[(u16, u16)]) = if eid == e::shipModuleTrackingDisruptor {
                    (SKILL_GUNNERY, false, &[(a::trackingSpeedBonus, a::trackingSpeed), (a::maxRangeBonus, a::maxRange), (a::falloffBonus, a::falloff)])
                } else {
                    (
                        SKILL_MISSILE_LAUNCHER_OPERATION,
                        true,
                        &[
                            (a::aoeCloudSizeBonus, a::aoeCloudSize),
                            (a::aoeVelocityBonus, a::aoeVelocity),
                            (a::missileVelocityBonus, a::maxVelocity),
                            (a::explosionDelayBonus, a::explosionDelay),
                        ],
                    )
                };
                for &(src, tgt) in pairs {
                    one.push(ProjAction::ModItems { skill, charge, attr: tgt, v: g(src), factor: f, resist, assist: false });
                }
            }
            e::entityEnergyNeutralizerFalloff => {
                if !cutoff(a::energyNeutralizerRangeOptimal) {
                    let amount = g(a::energyNeutralizerAmount);
                    one.push(ProjAction::Drain(ExtDrain {
                        cycle_ms: g(a::energyNeutralizerDuration),
                        amount,
                        resist,
                        sig_res: g(a::energyNeutralizerSignatureResolution),
                        assistance: false, late: false,
                    }));
                }
            }
            _ => {
                let opt = if meta.range != 0 { g(meta.range) } else { 0.0 };
                let fo = if meta.falloff != 0 { g(meta.falloff) } else { 0.0 };
                let factor = crate::stats::range_factor(opt, fo, distance, true);
                let mut list: Vec<(u16, u16, i8)> = Vec::new();
                let has_mods = d::apply_projected(ei as u16, &mut |t, s, op| list.push((t, s, op)));
                if !has_mods {
                    match meta.proj {
                        1 => list.push((a::maxVelocity, a::speedFactor, 6)),
                        2 => list.push((a::signatureRadius, a::signatureRadiusBonus, 6)),
                        3 | 4 => {
                            list.push((a::maxTargetRange, a::maxTargetRangeBonus, 6));
                            list.push((a::scanResolution, a::scanResolutionBonus, 6));
                            if meta.proj == 4 {
                                list.push((a::scanGravimetricStrength, a::scanGravimetricStrengthPercent, 6));
                                list.push((a::scanMagnetometricStrength, a::scanMagnetometricStrengthPercent, 6));
                                list.push((a::scanRadarStrength, a::scanRadarStrengthPercent, 6));
                                list.push((a::scanLadarStrength, a::scanLadarStrengthPercent, 6));
                            }
                        }
                        _ => one.push(ProjAction::Warn(format!("projected effect '{}' not modelled yet", d::eff_name(ei)))),
                    }
                }
                for (t, s, op) in list {
                    one.push(ProjAction::Mod { attr: t, op, v: g(s), factor, resist, pen: pen_cat && !d::attr_stackable(t), off: false });
                }
            }
        }
        for _ in 0..times {
            for x in &one {
                out.push(match x {
                    ProjAction::Mod { attr, op, v, factor, resist, pen, off } => {
                        ProjAction::Mod { attr: *attr, op: *op, v: *v, factor: *factor, resist: *resist, pen: *pen, off: *off }
                    }
                    ProjAction::Rr { kind, amount, dur_s } => ProjAction::Rr { kind: *kind, amount: *amount, dur_s: *dur_s },
                    ProjAction::ModItems { skill, charge, attr, v, factor, resist, assist } => {
                        ProjAction::ModItems { skill: *skill, charge: *charge, attr: *attr, v: *v, factor: *factor, resist: *resist, assist: *assist }
                    }
                    ProjAction::Drain(dr) => ProjAction::Drain(*dr),
                    ProjAction::Ecm { st, resist } => ProjAction::Ecm { st: *st, resist: *resist },
                    ProjAction::Warn(w) => ProjAction::Warn(w.clone()),
                });
            }
        }
    }
}
